package main

import \(
	""fmt""
	""github.com/dop251/goja""
\)

func main\(\) {
	vm := goja.New\(\)

	// Test 1: Invalid syntax
	script1 := ""var a var b""
	wrappedScript1 := fmt.Sprintf\(""\(function\(\) { %s }\)\(\)"", script1\)
	_, err := goja.Compile\(""test1"", wrappedScript1, false\)
	if err != nil {
		fmt.Println\(""Test 1 \(var a var b\): SYNTAX ERROR -"", err\)
	} else {
		fmt.Println\(""Test 1 \(var a var b\): NO ERROR \(unexpected\)""\)
	}

	// Test 2: Valid syntax
	script2 := ""return { test: 1 };""
	wrappedScript2 := fmt.Sprintf\(""\(function\(\) { %s }\)\(\)"", script2\)
	_, err = goja.Compile\(""test2"", wrappedScript2, false\)
	if err != nil {
		fmt.Println\(""Test 2 \(return {test:1}\): SYNTAX ERROR -"", err\)
	} else {
		fmt.Println\(""Test 2 \(return {test:1}\): NO ERROR \(expected\)""\)
	}
}
EOF
cd /tmp && go run test_syntax.go')
